WITH base AS (SELECT id, customer_id, device, browser, started_at, country, DATE_FORMAT(started_at, 'MMM yyyy') AS started_at_label, CAST(started_at AS DATE) AS started_at_day FROM sessions WHERE browser IS NOT NULL AND country IS DISTINCT FROM 'DE'), with_gaps AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) > INTERVAL '30' DAY THEN 1 ELSE 0 END AS session_start_flag FROM base), sessions_sessions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT country, COUNT(*) AS event_count, AVG(session_id) FILTER (WHERE device = 'mobile') AS mobile_avg_session_id, SORT_ARRAY(COLLECT_SET(device)) AS device_list, COUNT(*) FILTER (WHERE browser = 'Firefox') AS firefox_rows FROM sessions_sessions GROUP BY country HAVING AVG(session_id) FILTER (WHERE device = 'mobile') < 1000000 ORDER BY event_count NULLS LAST
